#[test]
fn test_the_render_rectangle_is_padded_floored_ceiled_and_held_to_the_page() {
    let res: &mut crate::port::Cells = &mut crate::port::Cells::new();
    af_rect(res, 10000, 10000, 30000, 30000, 150, 4194304);
    crate::testport::assert_eq(crate::port::cells_at(res, 0), 150, "the setting's dpi when it fits");
    crate::testport::assert_eq(crate::port::cells_at(res, 1), 204, "px = floor(9800 * 150 / 7200)");
    crate::testport::assert_eq(crate::port::cells_at(res, 2), 204, "py likewise");
    crate::testport::assert_eq(crate::port::cells_at(res, 3), 426, "pw = ceil(30200 * 150 / 7200) - px = 630 - 204");
    crate::testport::assert_eq(crate::port::cells_at(res, 4), 426, "ph likewise");
    // the pad is clipped to the page: a region at the corner starts at pixel 0
    af_rect(res, 0, 0, 1000, 1000, 150, 4194304);
    crate::testport::assert_eq(crate::port::cells_at(res, 1), 0, "px 0");
    crate::testport::assert_eq(crate::port::cells_at(res, 3), 25, "ceil(1200 * 150 / 7200) = 25");
    // and its far edge is the whole page's size, floor(w * d / 7200 + 1/2) pixels (1275 at 150 dpi)
    af_rect(res, 60000, 78000, 61200, 79200, 150, 4194304);
    crate::testport::assert_eq(crate::port::cells_at(res, 1), 1245, "px = floor(59800 * 150 / 7200)");
    crate::testport::assert_eq(crate::port::cells_at(res, 3), 30, "to the page's edge, pixel 1275");
    crate::testport::assert_eq(crate::port::cells_at(res, 4), 30, "in y too");
}
#[test]
fn test_too_many_pixels_step_the_dpi_down_by_three_quarters() {
    let res: &mut crate::port::Cells = &mut crate::port::Cells::new();
    af_rect(res, 10000, 10000, 30000, 30000, 150, 100000);
    crate::testport::assert_eq(crate::port::cells_at(res, 0), 84, "150 -> 112 (426 squared is over 100000, 318 squared too) -> 84");
    crate::testport::assert_eq(crate::port::cells_at(res, 1), 114, "px at 84 dpi");
    crate::testport::assert_eq(crate::port::cells_at(res, 3), 239, "pw at 84 dpi: 239 * 239 fits");
    af_rect(res, 10000, 10000, 30000, 30000, 150, 100);
    crate::testport::assert_eq(crate::port::cells_at(res, 0), 0, "under 36 dpi: too large");
    af_rect(res, 10000, 20000, 40000, 50000, 72, 4194304);
    crate::testport::assert_eq(crate::port::cells_at(res, 0), 72, "the given dpi, not 150");
    crate::testport::assert_eq(crate::port::cells_at(res, 3), 304, "304 pixels across");
    af_rect(res, 5000, 5000, 5000, 5000, 150, 4194304);
    crate::testport::assert_eq(crate::port::cells_at(res, 0), 150, "a point is still a rectangle (the pad makes it one)");
}
