#[test]
fn test_a_raster_figure_asks_for_its_frame_and_is_the_pixels_of_its_rectangle() {
    let res: &mut crate::port::Cells = &mut crate::port::Cells::new();
    af_raster(res, 0);
    crate::testport::assert_eq(crate::port::cells_at(res, 0), 8, "one request of eight cells (header, input, offset, length, filter, frame)");
    crate::testport::assert_eq(crate::port::cells_at(res, 1), 1, "one record");
    crate::testport::assert_eq(crate::port::cells_at(res, 2), pk_decode(), "a decode");
    crate::testport::assert_eq(crate::port::cells_at(res, 3), au_id(au_decode()), "of frame 0, under the asset unit's id");
    crate::testport::assert_eq(crate::port::cells_at(res, 4), 3, "of the input");
    crate::testport::assert_eq(crate::port::cells_at(res, 5), 0, "from its first byte");
    crate::testport::assert_eq(crate::port::cells_at(res, 6), 1234, "to its last");
    crate::testport::assert_eq(crate::port::cells_at(res, 7), flt_none(), "a whole image file");
    crate::testport::assert_eq(crate::port::cells_at(res, 8), 0, "frame 0");
    af_raster(res, 1);
    crate::testport::assert_eq(crate::port::cells_at(res, 0), 0, "with the answer nothing more is asked");
    crate::testport::assert_eq(crate::port::cells_at(res, 9), 1, "one asset");
    crate::testport::assert_eq(crate::port::cells_at(res, 10), 0, "the figure has it");
    crate::testport::assert_eq(crate::port::cells_at(res, 11), -1, "and no reason");
    crate::testport::assert_eq(crate::port::cells_at(res, 12), ao_cropped(), "cropped");
    crate::testport::assert_eq(crate::port::cells_at(res, 13), afm_png(), "from a PNG input");
    crate::testport::assert_eq(crate::port::cells_at(res, 14), 101, "101 pixels across: floor(20000 * 306 / 61200) = 100 to ceil(40100 * 306 / 61200) = 201");
    crate::testport::assert_eq(crate::port::cells_at(res, 15), 101, "and down: 150 to 251");
    crate::testport::assert_eq(crate::port::cells_at(res, 16), 0, "no render dpi");
    crate::testport::assert_eq(crate::port::cells_at(res, 17), 0, "no flags");
    crate::testport::assert_eq(crate::port::cells_at(res, 18), 1, "the PNG is the pixels of the rectangle, byte for byte, with no resampling");
}
