pub(crate) fn af_source(mut res: &mut crate::port::Cells, which: i32) -> i32 {
    // One figure that is the candidate `which` names, no answers; the number of requests it makes and its reason (or -1):
    // 0 a whole image (status 0, no flags): its own, no request; 1 the same with `overlaid`; 2 `colorspace`; 3 `codec`; 4 `part` (page-sized);
    // 5 `too-large`; 6 `budget`; 7 a region candidate; 8 a whole image that is `clip-bbox`; 9 `transformed`.
    let nodes: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let attrs: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let regions: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let text: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let pages: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let ledger: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let layout: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let assets: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let uses: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let cand: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let ans: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let rq: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let r#box: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let ws: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let rows: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let tmp: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let rec: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let cbytes: &mut crate::port::Buf = &mut crate::port::Buf::new();
    let abytes: &mut crate::port::Buf = &mut crate::port::Buf::new();
    let z: &mut crate::port::Buf = &mut crate::port::Buf::new();
    let bms: &crate::port::BitmapSet = &crate::port::BitmapSet::new();
    let mut status: i32 = 0;
    let mut flags: i32 = 0;
    let mut kori: i32 = -1;
    let mut n: i32 = 0;
    model_init(nodes, attrs, regions, text, pages, ledger, layout);
    page_new(pages, 1, 61200, 79200, 0, pk_vector());
    crate::port::buf_push(cbytes, 97);
    crate::port::buf_push(cbytes, 97);
    crate::port::buf_push(cbytes, 97);
    crate::port::buf_push(cbytes, 97);
    if which == 1 {
        flags = afg_overlaid();
    }
    if which == 2 {
        status = nz_colorspace();
    }
    if which == 3 {
        status = nz_codec();
    }
    if which == 4 {
        status = nz_part();
    }
    if which == 5 {
        status = nz_too_large();
    }
    if which == 6 {
        status = nz_budget();
    }
    if which == 7 {
        status = nz_vector();
        kori = -2;
    }
    if which == 8 {
        flags = 2;
    }
    if which == 9 {
        flags = 4;
    }
    if which == 4 {
        af_cand(cand, 1, 0, 0, 61200, 79200, status, flags, kori, 5, 0, 4);
    } else {
        af_cand(cand, 1, 10000, 10000, 30000, 30000, status, flags, kori, 5, 0, 4);
    }
    if which == 4 {
        n = af_node(nodes, regions, 0, nk_figure(), fg_unknown(), 1, 0, 0, 61200, 79200);
    } else {
        n = af_node(nodes, regions, 0, nk_figure(), fg_unknown(), 1, 10000, 10000, 30000, 30000);
    }
    node_set_attr_int(nodes, attrs, n, fk_image(), 0);
    af_boxcells(r#box);
    as_run_figures(nodes, attrs, regions, pages, cand, cbytes, assets, uses, abytes, 4194304, 33554432, 0, 150, 4194304, 3, 1234, 0, ans, rq, bms, ws, z, rows, tmp, rec, r#box);
    crate::port::cells_drop(res, 0);
    crate::port::cells_push(res, rec_count(rq));
    crate::port::cells_push(res, node_attr_int_or(nodes, attrs, n, fk_noasset(), -1));
    crate::port::cells_push(res, node_attr_int_or(nodes, attrs, n, fk_asset(), -1));
    return 0;
}
#[test]
fn test_which_figures_are_the_image_and_which_are_rendered() {
    let res: &mut crate::port::Cells = &mut crate::port::Cells::new();
    af_source(res, 0);
    crate::testport::assert_eq(crate::port::cells_at(res, 0), 0, "a whole clean image is its own: no request");
    crate::testport::assert_eq(crate::port::cells_at(res, 2), 0, "it is asset 0");
    af_source(res, 1);
    crate::testport::assert_eq(crate::port::cells_at(res, 0), 1, "paint over it (overlaid): rendered, a crop is asked");
    af_source(res, 8);
    crate::testport::assert_eq(crate::port::cells_at(res, 0), 1, "a clip that is not a rectangle (clip-bbox): rendered");
    af_source(res, 9);
    crate::testport::assert_eq(crate::port::cells_at(res, 0), 1, "a placement that is not rectilinear (transformed): rendered");
    af_source(res, 2);
    crate::testport::assert_eq(crate::port::cells_at(res, 0), 1, "colorspace at images is rendered at figures");
    af_source(res, 3);
    crate::testport::assert_eq(crate::port::cells_at(res, 0), 1, "so is codec");
    af_source(res, 4);
    crate::testport::assert_eq(crate::port::cells_at(res, 0), 1, "a page-sized image in a PDF is rendered (its pixels need the host's decode-img, D563)");
    af_source(res, 7);
    crate::testport::assert_eq(crate::port::cells_at(res, 0), 1, "a region candidate is rendered");
    af_source(res, 5);
    crate::testport::assert_eq(crate::port::cells_at(res, 0), 0, "an image too large is not rendered");
    crate::testport::assert_eq(crate::port::cells_at(res, 1), nz_too_large(), "it says so");
    af_source(res, 6);
    crate::testport::assert_eq(crate::port::cells_at(res, 0), 0, "a budget reason is the candidate's own");
    crate::testport::assert_eq(crate::port::cells_at(res, 1), nz_budget(), "it says so");
}
