pub(crate) fn af_path(mut pa: &mut crate::port::Cells, page: i32, x0: i32, y0: i32, x1: i32, y1: i32, flags: i32, vis: i32) -> i32 {
    // A path row (stride 24) with a page, a box, flags (`pg`: clip 4) and a verdict (`vis`, cell 19).
    let r: i32 = crate::port::cells_len(pa) / 24;
    let mut f: i32 = 0;
    while f < 24 {
        crate::port::cells_push(pa, 0);
        f += 1;
    }
    crate::port::cells_set(pa, (r * 24) + 0, page);
    crate::port::cells_set(pa, (r * 24) + 2, x0);
    crate::port::cells_set(pa, (r * 24) + 3, y0);
    crate::port::cells_set(pa, (r * 24) + 4, x1);
    crate::port::cells_set(pa, (r * 24) + 5, y1);
    crate::port::cells_set(pa, (r * 24) + 11, flags);
    crate::port::cells_set(pa, (r * 24) + 19, vis);
    return r;
}
pub(crate) fn af_pages(mut pg: &mut crate::port::Cells, n: i32) -> i32 {
    // n page records (16 cells) of 612 x 792 pt: media and crop box, no rotation.
    let mut i: i32 = 0;
    while i < n {
        crate::port::cells_push(pg, 0);
        crate::port::cells_push(pg, 0);
        crate::port::cells_push(pg, 0);
        crate::port::cells_push(pg, 61200);
        crate::port::cells_push(pg, 79200);
        crate::port::cells_push(pg, 0);
        crate::port::cells_push(pg, 0);
        crate::port::cells_push(pg, 61200);
        crate::port::cells_push(pg, 79200);
        crate::port::cells_push(pg, 0);
        crate::port::cells_push(pg, 0);
        crate::port::cells_push(pg, 0);
        crate::port::cells_push(pg, 0);
        crate::port::cells_push(pg, 0);
        crate::port::cells_push(pg, 0);
        crate::port::cells_push(pg, 0);
        i += 1;
    }
    return 0;
}
#[test]
fn test_vector_art_is_a_cluster_of_paths() {
    // page 1: four paths 1 pt apart (a chart's axes and bars) form one region; two far-off paths are no figure (a lone path is a rule); a clip
    // and a hidden path join nothing; a page-sized path (a background) is not part of one. Page 2: three paths that sit
    // under an image's visible box are the image's, not a region. Page 3: a cluster narrower than 18 pt is no figure.
    let pa: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let pg: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let cand: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let cl: &mut crate::port::Cells = &mut crate::port::Cells::new();
    af_pages(pg, 3);
    af_path(pa, 1, 10000, 10000, 30000, 10100, 0, 0);
    af_path(pa, 1, 10000, 10000, 10100, 30000, 0, 0);
    af_path(pa, 1, 10200, 20000, 15000, 29900, 0, 0);
    af_path(pa, 1, 15100, 18000, 18000, 29900, 0, 0);
    af_path(pa, 1, 40000, 60000, 50000, 60100, 0, 0);
    af_path(pa, 1, 45000, 70000, 50000, 70100, 0, 0);
    af_path(pa, 1, 20000, 12000, 30000, 25000, 4, 0);
    af_path(pa, 1, 20000, 40000, 30000, 45000, 0, 3);
    af_path(pa, 1, 0, 0, 61200, 79200, 0, 0);
    af_path(pa, 2, 10000, 10000, 30000, 10100, 0, 0);
    af_path(pa, 2, 10000, 10000, 10100, 30000, 0, 0);
    af_path(pa, 2, 10200, 20000, 15000, 29900, 0, 0);
    af_path(pa, 3, 10000, 10000, 11500, 10100, 0, 0);
    af_path(pa, 3, 10000, 10000, 10100, 11500, 0, 0);
    af_path(pa, 3, 10800, 10800, 11500, 10900, 0, 0);
    // the image on page 2: a candidate row of kind -1 over the whole cluster
    af_cand(cand, 2, 5000, 5000, 35000, 35000, 0, 0, -1, 1, 0, 0);
    as_vector_regions(pa, pg, cand, cl);
    crate::testport::assert_eq(as_count(cand), 2, "the image's row and one region");
    crate::testport::assert_eq(as_get(cand, 1, 0), 1, "on page 1");
    crate::testport::assert_eq(as_get(cand, 1, 5), 10000, "the cluster's left");
    crate::testport::assert_eq(as_get(cand, 1, 6), 10000, "its top");
    crate::testport::assert_eq(as_get(cand, 1, 7), 30000, "its right");
    crate::testport::assert_eq(as_get(cand, 1, 8), 30000, "its bottom");
    crate::testport::assert_eq(as_get(cand, 1, 27), -2, "a region candidate");
    crate::testport::assert_eq(as_get(cand, 1, 9), nz_vector(), "whose status is vector");
}
